// NODE 2 — Validate Payload
const item = $input.first();
const body = item.json.body || item.json;

const phone = (body.phone || '').toString().trim();
const delayHoursRaw = body.delay_hours;
let delayHours = Number(delayHoursRaw);
if (!Number.isFinite(delayHours) || delayHours <= 0 || delayHours > 168) {
  delayHours = 24;
}

// Strict E.164 +1 US format check
if (!/^\+1\d{10}$/.test(phone)) {
  // Invalid → stop with explicit flag
  return [{ json: { valid: false, validation_error: 'invalid_phone', received_payload: body } }];
}

return [{
  json: {
    valid: true,
    phone,
    name: body.name || null,
    service_requested: body.service_requested || 'your inquiry',
    intent_score: Number(body.intent_score) || 50,
    follow_up_question: body.follow_up_question || null,
    lead_ref: body.lead_ref || null,
    delay_hours: delayHours
  }
}];

// NODE — Status Gate
// Looks up the lead row(s) and the opt_outs table, then decides whether to proceed.
const payload = $('Validate Payload').first().json;
const leadRows = $items('Lookup Current Lead Status').map(i => i.json).filter(r => r && r.phone);
const optOutRows = $items('Read Opt-Outs (Safety Recheck)').map(i => i.json).filter(r => r && r.phone);

const phone = payload.phone;
const leadRef = payload.lead_ref;

// 1) Opt-out hard stop
const isOptedOut = optOutRows.some(r => (r.phone || '').toString().trim() === phone);
if (isOptedOut) {
  return [{ json: { ...payload, should_send: false, stop_reason: 'opted_out_at_followup_time' } }];
}

if (!leadRows.length) {
  return [{ json: { ...payload, should_send: false, stop_reason: 'lead_row_not_found' } }];
}

// 2) Find the right lead row — prefer match on lead_ref (id column), else most recent
let targetRow = null;
if (leadRef) {
  targetRow = leadRows.find(r => (r.id || '').toString() === leadRef.toString()) || null;
}
if (!targetRow) {
  targetRow = leadRows.slice().sort((a, b) => Date.parse(b.timestamp || 0) - Date.parse(a.timestamp || 0))[0];
}

const currentStatus = (targetRow.status || '').toLowerCase().trim();
const STOP_STATUSES = ['booked', 'closed', 'opted_out', 'contacted_high', 'follow_up_sent'];
if (STOP_STATUSES.includes(currentStatus)) {
  return [{ json: { ...payload, should_send: false, stop_reason: 'status_already_' + currentStatus, current_status: currentStatus, row_id: targetRow.id, row_phone: targetRow.phone } }];
}

if (currentStatus !== 'follow_up_scheduled') {
  return [{ json: { ...payload, should_send: false, stop_reason: 'unexpected_status_' + currentStatus, current_status: currentStatus } }];
}

return [{
  json: {
    ...payload,
    should_send: true,
    current_status: currentStatus,
    row_id: targetRow.id,
    row_phone: targetRow.phone,
    row_existing_notes: targetRow.notes || ''
  }
}];

// NODE — Build Follow-Up SMS
const d = $json;
const firstName = d.name ? String(d.name).trim().split(/\s+/)[0] : null;
const greeting = firstName ? `Hi ${firstName},` : 'Hi there,';
const biz = $env.BUSINESS_NAME || 'us';
const svc = d.service_requested || 'your inquiry';
const booking = ($env.BOOKING_LINK || '').trim();
const phone = $env.BUSINESS_PHONE || '';

let body;
if (booking) {
  body = `${greeting} just following up from ${biz}! Still interested in ${svc}? You can book directly here: ${booking} — Reply STOP to opt out.`;
} else {
  body = `${greeting} just following up from ${biz}! Still interested in ${svc}? Give us a call at ${phone} — we'd love to help. — Reply STOP to opt out.`;
}
return [{ json: { ...d, sms_body: body } }];

// Prepare update payload — append timestamp note to existing notes
const d = $json;
const nowIso = new Date().toISOString();
const existingNotes = d.row_existing_notes || '';
const newNote = `${existingNotes}\n[${nowIso}]: 24h follow-up SMS sent`.trim();
return [{ json: { ...d, _update_status: 'follow_up_sent', _update_notes: newNote, _update_last_contact: nowIso } }];

const item = $input.first();
const params = item.json.body || item.json;
return [{ 
  json: { 
    ...params, 
    _sig_validated: false, 
    _sig_skipped: true, 
    _twilio_message_sid: params.MessageSid || null 
  } 
}];

// NODE 4 — Opt-Out & Compliance Keyword Detection
// Reads original Twilio payload from sig validation node, and opt_outs rows from the previous Sheets read.

const twilioItem = $('Twilio Signature Validation').first().json;
const optOutRows = $items('Read Opt-Outs Tab').map(i => i.json);

const fromRaw = (twilioItem.From || '').toString();
const body = (twilioItem.Body || '').toString().trim();
const bodyLower = body.toLowerCase();

// Normalize phone for comparison (strip non-digits, prefix +1 if 10 digit US)
function normalizePhone(p) {
  if (!p) return null;
  const digits = String(p).replace(/[^0-9]/g, '');
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  if (digits.length === 12) return '+' + digits.replace(/^\+/, '');
  if (String(p).startsWith('+') && digits.length >= 10) return '+' + digits;
  return null;
}

const phone = normalizePhone(fromRaw);

const OPT_OUT_KEYWORDS = ['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'];
const HELP_KEYWORDS = ['help', 'info'];
const START_KEYWORDS = ['start', 'unstop', 'yes', 'resubscribe'];

function matchesKeyword(text, list) {
  if (!text) return false;
  if (list.includes(text)) return true; // exact whole-message
  for (const k of list) {
    // Match as whole word
    const re = new RegExp('(^|\\s|[!?.,;])' + k + '($|\\s|[!?.,;])', 'i');
    if (re.test(text)) return true;
  }
  return false;
}

const isOptOut = matchesKeyword(bodyLower, OPT_OUT_KEYWORDS);
const isHelp = !isOptOut && matchesKeyword(bodyLower, HELP_KEYWORDS);
const isStart = !isOptOut && !isHelp && matchesKeyword(bodyLower, START_KEYWORDS);

// Check if already in opt_outs sheet
let alreadyOptedOut = false;
let optOutRowIndex = null;
for (let i = 0; i < optOutRows.length; i++) {
  const r = optOutRows[i];
  const rowPhone = (r.phone || '').toString().trim();
  if (rowPhone === phone) {
    alreadyOptedOut = true;
    optOutRowIndex = i; // 0-based within data; sheet row = i + 2 (header offset)
    break;
  }
}

let action = 'continue';
if (isOptOut) action = 'opt_out';
else if (isHelp) action = 'help';
else if (isStart) action = 'start';
else if (alreadyOptedOut) action = 'already_opted_out';

return [{
  json: {
    ...twilioItem,
    phone_normalized: phone,
    body_clean_preview: body.substring(0, 200),
    action,
    already_opted_out: alreadyOptedOut,
    opt_out_row_index: optOutRowIndex,
    opt_out_sheet_row: optOutRowIndex != null ? (optOutRowIndex + 2) : null
  }
}];

// Resolve opt_out sheet row number for the inbound phone (1-based, with header at row 1)
const phone = $json.phone_normalized;
const rowIdx = $json.opt_out_sheet_row;
if (!rowIdx) {
  // Not actually in opt_outs — nothing to delete; emit empty so deletion node is a no-op.
  return [{ json: { ...$json, _delete_target_row: null } }];
}
return [{ json: { ...$json, _delete_target_row: rowIdx } }];

// NODE — Rate Limit (in-memory short-term throttle)
const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};

const phone = $json.phone_normalized;
const now = Date.now();

// Clean entries older than 10 min
const cutoff = now - 600000;
for (const k of Object.keys(staticData.rateLimits)) {
  if ((staticData.rateLimits[k] || 0) < cutoff) delete staticData.rateLimits[k];
}

const last = staticData.rateLimits[phone] || 0;
if (last && (now - last) < 60000) {
  console.log(`Rate limit hit for ${phone} — silently dropping inbound.`);
  return []; // silent drop, returns empty → execution stops on this branch
}
staticData.rateLimits[phone] = now;

return [{ json: { ...$json, rate_limit_pass: true, rate_limit_ts: now } }];

// NODE — Data Cleaning & Normalization
const src = $('Rate Limit Check').first().json;
const bodyRaw = (src.Body || '').toString();

// Phone already normalized upstream; re-validate strictly here.
const phone = src.phone_normalized;
if (!phone || !/^\+1\d{10}$/.test(phone)) {
  // Hand off to error path via a thrown error; caller has onError handling.
  return [{ json: { ...src, validation_failed: true, validation_error: 'invalid_phone' } }];
}

let body = bodyRaw.trim();
if (!body) {
  return []; // silent stop
}
if (body.length === 1) {
  return []; // single char
}
// Strip emoji + whitespace; if nothing left → pure emoji
const stripped = body.replace(/[\p{Extended_Pictographic}\p{Emoji_Presentation}\s]/gu, '');
if (stripped.length === 0) {
  return [];
}

if (body.length > 1000) body = body.substring(0, 1000);

const lower = body.toLowerCase();
const INJECTION_PATTERNS = [
  'ignore previous','ignore all','system:','assistant:',
  'new instruction','forget everything','you are now',
  'disregard','override'
];
let flagged = false;
let flaggedPattern = null;
for (const p of INJECTION_PATTERNS) {
  if (lower.includes(p)) { flagged = true; flaggedPattern = p; break; }
}

return [{
  json: {
    ...src,
    phone_normalized: phone,
    message_clean: body,
    message_length: body.length,
    injection_flagged: flagged,
    injection_pattern: flaggedPattern,
    validation_failed: false
  }
}];

// NODE — Deduplication Check
const clean = $('Data Cleaning').first().json;
const existing = $items('Lookup Existing Leads').map(i => i.json).filter(r => r && r.phone);

const now = new Date();
const sevenDaysAgo = now.getTime() - (7 * 24 * 60 * 60 * 1000);

// Find an active duplicate within 7 days
let duplicate = null;
for (const row of existing) {
  const status = (row.status || '').toLowerCase();
  if (status === 'closed' || status === 'opted_out') continue;
  const ts = Date.parse(row.timestamp);
  if (isNaN(ts)) continue;
  if (ts >= sevenDaysAgo) {
    if (!duplicate || ts > Date.parse(duplicate.timestamp)) duplicate = row;
  }
}

if (duplicate) {
  return [{
    json: {
      ...clean,
      is_duplicate: true,
      existing_lead_id: duplicate.id || null,
      existing_row_number: duplicate.row_number || duplicate.rowNumber || null,
      existing_notes: duplicate.notes || '',
      existing_phone: duplicate.phone
    }
  }];
}

return [{ json: { ...clean, is_duplicate: false, lead_is_new: true } }];

