const response = $input.first().json;
const priorLead = $('Deduplication Logic').first().json;

let rawText = '';
try {
  rawText = response.content[0].text;
} catch(e) {
  rawText = JSON.stringify(response);
}

rawText = String(rawText).trim();

let parsed = null;

try {
  parsed = JSON.parse(rawText);
} catch(e) {
  const first = rawText.indexOf('{');
  const last = rawText.lastIndexOf('}');
  if (first !== -1 && last !== -1) {
    try {
      parsed = JSON.parse(rawText.substring(first, last + 1));
    } catch(e2) {}
  }
}

if (!parsed) {
  return [{ json: { ...priorLead, parse_failed: true, raw_claude_response: rawText.substring(0, 200) }}];
}

const intent_score = Math.min(100, Math.max(0, parseInt(parsed.intent_score) || 50));
const urgency = ['low','medium','high'].includes(parsed.urgency) ? parsed.urgency : 'medium';
let recommended_action = ['book','followup','ignore'].includes(parsed.recommended_action) ? parsed.recommended_action : (intent_score >= 80 ? 'book' : intent_score >= 50 ? 'followup' : 'ignore');

return [{ json: {
  ...priorLead,
  parse_failed: false,
  name: parsed.name || null,
  service_requested: parsed.service_requested || 'your inquiry',
  urgency,
  intent_score,
  recommended_action,
  summary: parsed.summary || 'Lead submitted via SMS',
  follow_up_question: parsed.follow_up_question || null
}}];

const d = $json;
const firstName = d.name ? String(d.name).trim().split(/\s+/)[0] : null;
const greeting = firstName ? `Hi ${firstName},` : 'Hi there,';
const svc = d.service_requested || 'your inquiry';
const booking = (($env.BOOKING_LINK || '').trim());
const biz = ($env.BUSINESS_NAME || 'us');
const phone = ($env.BUSINESS_PHONE || '');

let body;
let booking_link_sent;
if (booking) {
  body = `${greeting} thanks for contacting ${biz}! We'd love to help with ${svc}. You can book here: ${booking} — Reply STOP to opt out.`;
  booking_link_sent = true;
} else {
  body = `${greeting} thanks for contacting ${biz}! Please give us a call at ${phone}. — Reply STOP to opt out.`;
  booking_link_sent = false;
}

return [{ json: { ...d, sms_body: body, booking_link_sent } }];

